import{_ as e,o,c as i,a2 as t}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 2","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_2.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_2.md"}'),r={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_2.md"};function n(s,a,c,l,d,u){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="manual-de-estudio-profundo-evaluacion-2" tabindex="-1">Manual de Estudio Profundo: Evaluación 2 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-2" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 2&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-el-diagnostico-participativo" tabindex="-1">Eje Temático: El Diagnóstico Participativo <a class="header-anchor" href="#eje-tematico-el-diagnostico-participativo" aria-label="Permalink to &quot;Eje Temático: El Diagnóstico Participativo&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-escucha-activa" tabindex="-1">🧭 Introducción: La Escucha Activa <a class="header-anchor" href="#🧭-introduccion-la-escucha-activa" aria-label="Permalink to &quot;🧭 Introducción: La Escucha Activa&quot;">​</a></h2><p>En la ingeniería de software clásica, antes de programar una solución, un analista de sistemas entrevista al cliente para saber qué necesita (Toma de Requerimientos). En el Proyecto Sociotecnológico (PST), este proceso tiene una dimensión humana mucho más profunda y se denomina <strong>Abordaje Comunitario</strong> y <strong>Diagnóstico Participativo</strong>.</p><p>No puedes llegar a una comunidad asumiendo que sabes lo que necesitan. Si llegas instalando una red Wi-Fi cuando el problema real es que las tres únicas computadoras de la escuela están quemadas por fallas eléctricas, tu proyecto será un fracaso absoluto (y un desperdicio de recursos). El éxito de tu proyecto radica en saber observar, preguntar y escuchar.</p><hr><h2 id="🏛️-capitulo-i-el-abordaje-comunitario" tabindex="-1">🏛️ CAPÍTULO I: El Abordaje Comunitario <a class="header-anchor" href="#🏛️-capitulo-i-el-abordaje-comunitario" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Abordaje Comunitario&quot;">​</a></h2><p>El abordaje es el primer contacto. Es el momento en el que dejas la universidad y te presentas ante los líderes de la comunidad (Consejos Comunales, directores de escuelas, jefes de ambulatorios).</p><h3 id="_1-1-reglas-de-oro-del-abordaje" tabindex="-1">1.1 Reglas de Oro del Abordaje <a class="header-anchor" href="#_1-1-reglas-de-oro-del-abordaje" aria-label="Permalink to &quot;1.1 Reglas de Oro del Abordaje&quot;">​</a></h3><ol><li><strong>Humildad Académica:</strong> No llegas como el &quot;salvador que todo lo sabe&quot;, llegas como un estudiante dispuesto a colaborar y aprender de la realidad local.</li><li><strong>Respeto a los Canales Regulares:</strong> Siempre debes presentarte primero ante las autoridades legítimas de la comunidad. No puedes intervenir una institución sin permiso de su directiva.</li><li><strong>Claridad de Alcance:</strong> Sé honesto sobre lo que puedes y no puedes hacer. En el Trayecto I tu alcance es <em>Soporte Técnico</em> y <em>Alfabetización Tecnológica</em>. No prometas desarrollar un software complejo (eso es para el Trayecto II y III).</li></ol><hr><h2 id="🧩-capitulo-ii-el-diagnostico-participativo" tabindex="-1">🧩 CAPÍTULO II: El Diagnóstico Participativo <a class="header-anchor" href="#🧩-capitulo-ii-el-diagnostico-participativo" aria-label="Permalink to &quot;🧩 CAPÍTULO II: El Diagnóstico Participativo&quot;">​</a></h2><p>Una vez aceptados en la comunidad, comienza la investigación formal.</p><h3 id="_2-1-definicion-y-finalidad" tabindex="-1">2.1 Definición y Finalidad <a class="header-anchor" href="#_2-1-definicion-y-finalidad" aria-label="Permalink to &quot;2.1 Definición y Finalidad&quot;">​</a></h3><p>El <strong>Diagnóstico Participativo</strong> es un proceso de recolección, sistematización y análisis de información, realizado <strong>en conjunto con los miembros de la comunidad</strong>, para conocer su realidad, identificar sus problemas y reconocer sus recursos potenciales. <em>Analogía:</em> Es como cuando un médico examina a un paciente. No puede recetar la medicina sin antes hacer preguntas, revisar los síntomas y quizás pedir exámenes de laboratorio. El diagnóstico participativo es la historia médica de la comunidad.</p><h3 id="_2-2-¿por-que-es-participativo" tabindex="-1">2.2 ¿Por qué es &quot;Participativo&quot;? <a class="header-anchor" href="#_2-2-¿por-que-es-participativo" aria-label="Permalink to &quot;2.2 ¿Por qué es &quot;Participativo&quot;?&quot;">​</a></h3><p>A diferencia de un diagnóstico tradicional (donde un experto externo evalúa de lejos y da su veredicto), en este enfoque <strong>la comunidad es protagonista</strong>. Ellos conocen mejor que nadie sus carencias y sus fortalezas. Tú aportas la estructura técnica, pero ellos aportan la realidad vivida.</p><h3 id="_2-3-normas-y-elementos-del-diagnostico" tabindex="-1">2.3 Normas y Elementos del Diagnóstico <a class="header-anchor" href="#_2-3-normas-y-elementos-del-diagnostico" aria-label="Permalink to &quot;2.3 Normas y Elementos del Diagnóstico&quot;">​</a></h3><ul><li><strong>Objetividad:</strong> Registrar lo que realmente ves, no lo que crees que pasa.</li><li><strong>Inclusividad:</strong> Escuchar a diferentes actores (no solo al líder, sino también a los usuarios, profesores, secretarias, etc.).</li><li><strong>Elementos a evaluar:</strong> Infraestructura (¿hay luz?, ¿hay internet?), Equipos (¿cuántas PC hay?, ¿qué daño tienen?), Capital Humano (¿saben usar las computadoras?).</li></ul><hr><h2 id="🏗️-capitulo-iii-levantamiento-de-informacion-herramientas" tabindex="-1">🏗️ CAPÍTULO III: Levantamiento de Información (Herramientas) <a class="header-anchor" href="#🏗️-capitulo-iii-levantamiento-de-informacion-herramientas" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Levantamiento de Información (Herramientas)&quot;">​</a></h2><p>Para que el diagnóstico tenga validez académica y científica (y sea aprobado por la UPSIT), la información no puede basarse en &quot;charlas de pasillo&quot;. Necesitas recolectar datos empíricos usando <strong>Técnicas e Instrumentos</strong>.</p><h3 id="_3-1-la-entrevista" tabindex="-1">3.1 La Entrevista <a class="header-anchor" href="#_3-1-la-entrevista" aria-label="Permalink to &quot;3.1 La Entrevista&quot;">​</a></h3><p>Es una conversación estructurada con informantes clave.</p><ul><li><strong>Uso ideal:</strong> Hablar con el director de una escuela o el vocero del consejo comunal para entender la historia del problema tecnológico.</li><li><strong>Instrumento:</strong> Guion de entrevista (una lista de preguntas abiertas).</li></ul><h3 id="_3-2-la-encuesta" tabindex="-1">3.2 La Encuesta <a class="header-anchor" href="#_3-2-la-encuesta" aria-label="Permalink to &quot;3.2 La Encuesta&quot;">​</a></h3><p>Es una recolección masiva de datos usando preguntas cerradas.</p><ul><li><strong>Uso ideal:</strong> Saber cuántas personas de un sector saben usar Word o Excel (Alfabetización).</li><li><strong>Instrumento:</strong> El Cuestionario (papel o digital).</li></ul><h3 id="_3-3-la-observacion-directa" tabindex="-1">3.3 La Observación Directa <a class="header-anchor" href="#_3-3-la-observacion-directa" aria-label="Permalink to &quot;3.3 La Observación Directa&quot;">​</a></h3><p>Es la comprobación visual en el campo por parte de los estudiantes.</p><ul><li><strong>Uso ideal:</strong> Revisar el estado físico de los equipos. Ver si los cables están pelados, si los monitores encienden o si hay polvo extremo en los gabinetes.</li><li><strong>Instrumento:</strong> Guía de observación o Lista de Cotejo (Checklist).</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>El Papel de la UPSIT</strong> Todo instrumento de recolección de datos (tus cuestionarios o guiones) debe ser validado por tu tutor técnico y académico antes de aplicarlo en la comunidad. Esto asegura que las preguntas estén bien formuladas y sean pertinentes a tu perfil de Informática.</p></div><p>En la próxima evaluación, aprenderemos qué hacer con toda esta montaña de información que acabas de recolectar: cómo organizarla, analizarla y devolverla a la comunidad.</p>',35)])])}const h=e(r,[["render",n]]);export{p as __pageData,h as default};
